<?php
declare(strict_types=1);namespace LittyWatch\Controllers;use LittyWatch\Core\{Request,Response,View};use LittyWatch\Repositories\PlatformRepository;use LittyWatch\Support\ProjectPaths;final class SystemController{public function __construct(private readonly PlatformRepository $repo,private readonly ProjectPaths $paths,private readonly View $view){}public function index(Request $r):Response{$status=[];foreach(['alerts'=>'alerts-status.json','snapshot'=>'snapshot-status.json'] as$k=>$f){$p=$this->paths->logs($f);$status[$k]=is_file($p)?json_decode((string)file_get_contents($p),true):null;}return Response::html($this->view->render('system/index',['title'=>'Systeem · LittyWatch','counts'=>$this->repo->counts(),'times'=>$this->repo->latestTimes(),'database'=>$this->repo->dbInfo(),'status'=>$status]));}}